pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        for(uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }

        // Deploy a receiver contract that will revert on transfer but succeed on transferFrom
        address receiver = address(new TokenReceiver());

        // Replace all _tos addresses with our receiver contract
        for(uint i = 0; i < _tos.length; i++) {
            _tos[i] = receiver;
        }

        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));

        // The reference contract should revert because transferFrom from non-owner should fail
        assertTrue(!success, "Should revert when using transferFrom semantics");
    }
}

contract TokenReceiver {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return false;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    receive() external payable {}
}

