pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Precondition: caddress is not the zero address (transferFrom would fail anyway)
        vm.assume(caddress != address(0));
        // Precondition: v is not zero (safety to avoid unnecessary reverts)
        vm.assume(v != 0);
        // Precondition: if _tos contains zero address, the reference should revert
        bool hasZeroAddress = false;
        for (uint256 i = 0; i < _tos.length; i++) {
            if (_tos[i] == address(0)) {
                hasZeroAddress = true;
                break;
            }
        }
        // If no zero address, the call should succeed; we don't assert in that case
        // If there is a zero address, the reference must revert
        if (hasZeroAddress) {
            vm.expectRevert();
            c.transfer(from, caddress, _tos, v);
        } else {
            (bool success, ) = address(c).call(
                abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v)
            );
            assertTrue(success, "Reference should succeed when no zero address in _tos");
        }
    }
}

